"""Check the edge reader against silhouettes whose edges are known, generated by the
site's own cut geometry.

piececutter.py is a port of PieceCutter.drawEdge, so piececutter.piece_mask(edges) is the
exact outline the browser draws for a piece with those edges.  That makes a ground-truth
test possible with no mouse and no guessing: render a piece, paint it with a texture, drop
it on the board's background colour, then ask probe_edges.read_edges what it sees.

  python test_edges.py [--trials 300]
"""
from __future__ import annotations

import argparse
import random
from collections import Counter, defaultdict

import cv2
import numpy as np

import piececutter as pc
import probe_edges as pe

PW, PH = 112.0, 85.0
PAD = 40


def render(edges, rng: random.Random, shadow: bool = True
           ) -> tuple[np.ndarray, tuple[int, int, int, int]]:
    """A piece with `edges`, on the board's background, plus its box.

    The engine does two things a naive sprite would not: it strokes the outline in 40% white, and
    it drops a soft shadow about 20 px below and to the right.  The stroke has always been here;
    the shadow is added because the flat-side reading fails on the real screen (0 to 4 flats out
    of 25) while it is exact on synthetic input, and the shadow is the obvious difference -- it
    darkens the very gap that a flat side is supposed to leave empty.
    """
    mask = pc.piece_mask(tuple(edges), PW, PH)
    ch, cw = mask.shape
    canvas = np.zeros((ch + 2 * PAD, cw + 2 * PAD, 3), np.uint8)
    canvas[:, :] = (43, 23, 17)                      # the board placeholder, BGR
    # A photo is not per-pixel noise: it is a smooth field with local structure.  Feeding
    # per-pixel noise would make Canny fire everywhere and the test would measure the test
    # instead of the reader -- which is exactly what happened on the first attempt.
    rng_np = np.random.default_rng(rng.randrange(1 << 30))
    small = rng_np.integers(0, 256, (12, 16, 3), np.uint8)
    texture = cv2.resize(small, (canvas.shape[1], canvas.shape[0]), interpolation=cv2.INTER_CUBIC)
    texture = cv2.GaussianBlur(texture, (0, 0), 1.2)
    m = np.zeros(canvas.shape[:2], np.uint8)
    m[PAD:PAD + ch, PAD:PAD + cw] = mask
    if shadow:
        off = np.float32([[1, 0, 7], [0, 1, 12]])
        sh = cv2.warpAffine((m * 255), off, (canvas.shape[1], canvas.shape[0]))
        sh = cv2.GaussianBlur(sh, (0, 0), 5.0).astype(np.float32) / 255.0
        canvas = (canvas.astype(np.float32) * (1.0 - 0.5 * sh[..., None])).astype(np.uint8)
    canvas[m == 1] = texture[m == 1]
    # the engine strokes the piece outline in 40% white
    cont, _ = cv2.findContours(m, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
    cv2.drawContours(canvas, cont, -1, (255, 255, 255), 1)
    _tab, margin, _cw, _ch = pc.geometry(PW, PH)
    box = (PAD + int(round(margin)), PAD + int(round(margin)), int(PW), int(PH))
    return canvas, box


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--trials", type=int, default=300)
    ap.add_argument("--no-shadow", action="store_true",
                    help="render without the engine's drop shadow, to compare against the "
                         "shadowed case and see whether the shadow is what breaks flat sides")
    args = ap.parse_args()
    rng = random.Random(2026)

    scores: dict[str, dict[str, list[float]]] = defaultdict(lambda: defaultdict(list))
    hits = Counter()
    total = Counter()
    for _ in range(args.trials):
        # Only legal pieces: a 5x5 game gives corners two flat sides, frame pieces one,
        # interior pieces and decoys none.  Three or four flat sides cannot occur, and the
        # reader deliberately rejects those readings, so generating them would only measure
        # the rejection path.
        n_flat = rng.choices((0, 1, 2), weights=(14, 12, 4))[0]
        flat_at = set(rng.sample(range(4), n_flat))
        edges = tuple(pc.FLAT if i in flat_at else rng.choice((pc.TAB, pc.NOTCH))
                      for i in range(4))
        img, box = render(edges, rng, shadow=not args.no_shadow)
        names = ("top", "right", "bottom", "left")
        # piececutter's signs describe the *path offset*: +1 bends inward (a dent, which the
        # reader calls 'notch'), -1 bends outward (a bulge, 'tab').  The reader reports the
        # visual fact, so the mapping is flipped here on purpose.
        want = {n: {pc.TAB: "notch", pc.NOTCH: "tab", pc.FLAT: "flat"}[e]
                for n, e in zip(names, edges)}
        got = pe.read_edges(img, box)
        tab_sc, notch_sc = {}, {}
        m, (x0, y0), _bg = pe.piece_mask(img, box)
        bx, by = box[0] - x0, box[1] - y0
        for n in names:
            out_p = pe.side_profile(m, bx, by, int(PW), int(PH), n, outward=True)
            in_p = pe.side_profile(m, bx, by, int(PW), int(PH), n, outward=False)
            tab_sc[n] = max(pe.middle_vs_ends(out_p[d]) for d in range(1, len(out_p)))
            notch_sc[n] = max(pe.middle_vs_ends(1.0 - in_p[d]) for d in range(1, len(in_p)))
            scores[want[n]]["tab"].append(tab_sc[n])
            scores[want[n]]["notch"].append(notch_sc[n])
        for n in names:
            total[want[n]] += 1
            hits[(want[n], got[n])] += 1

    print(f"{args.trials} synthetic pieces, {sum(total.values())} sides")
    for kind in ("tab", "notch", "flat"):
        print(f"  {kind:6s} right {hits[(kind, kind)]:4d}/{total[kind]:4d} "
              f"({hits[(kind, kind)] / max(1, total[kind]):.1%})")
        wrong = {k: v for k, v in hits.items() if k[0] == kind and k[1] != kind}
        if wrong:
            print(f"         confusions {dict(wrong)}")
    print("\nscore distributions (what the threshold has to separate)")
    for kind in ("tab", "notch", "flat"):
        for measure in ("tab", "notch"):
            vals = sorted(scores[kind][measure])
            if not vals:
                continue
            print(f"  truth {kind:6s} {measure:5s} score: "
                  f"p05 {vals[len(vals)//20]:.2f}  median {vals[len(vals)//2]:.2f}  "
                  f"p95 {vals[-max(1, len(vals)//20)]:.2f}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
